query get_user_by_id($id: ID!) {
  user(id: $id) {
    id
    name
    email
  }
}

fragment user_fields on User {
  id
  name
  email
}

query get_all_users {
  users {
    ...user_fields
  }
}

fragment post_fields on Post {
  id
  title
  content
}

query get_posts_with_fragment {
  posts {
    ...post_fields
    author {
      id
      name
    }
  }
}

mutation create_post($title: String!, $content: String!) {
  createPost(title: $title, content: $content) {
    id
    title
    content
  }
}

# Test nested fragments
fragment address_fields on Address {
  street
  city
  country
}

fragment user_with_address on User {
  id
  name
  ...address_fields
}

query get_users_with_addresses {
  users {
    ...user_with_address
  }
}

